      "granularity_name": "other"
    },
    {
      "chord_quality": "sus4",
      "function_role": "modal-transposition-vehicle",
      "narrative": "When rhythmizing scale sequences, Bergonzi directs the student to play the pattern starting from every degree of the scale modally over a sus4 chord, making it the recommended harmonic backdrop for systematic modal transposition practice. 'First play the pattern starting from every degree of the scale (in other words modally transposing it). In the example below all of the notes are played over a dominant sus 4 chord.' Chapter 28, p. 113.",
      "source_principle_ids": [
        "jerry-bergonzi:melodic-rhythms-vol-4:polyrhythmic-construction"
      ],
      "source_work_id": "melodic-rhythms-vol-4",
