    },
    {
      "chord_quality": "dom7",
      "function_role": "triplet-gear-truncation-application",
      "narrative": "When recasting any eighth-note line into triplet gear over a dominant (or any) context, Bergonzi prescribes leaving off either the first four or the last four notes of an eight-note phrase to make the line fit comfortably in triplet subdivision. 'To make this line feel comfortable in triplet gear you need to leave off the first four or the last four notes. In this case we'll leave off the last four.' Chapter 19, p. 83.",
      "source_principle_ids": [
        "jerry-bergonzi:melodic-rhythms-vol-4:time-zone-gear-system"
      ],
      "source_work_id": "melodic-rhythms-vol-4",
