      "granularity_name": "other"
    },
    {
      "chord_quality": "dom7",
      "function_role": "pocket-eighth-note-placement",
      "narrative": "Bergonzi prescribes that in jazz playing, eighth notes over a dominant groove should coexist with the triplet feel rather than literally become triplets \u2014 sometimes by laying back or applying a lob. 'One way to improve your feel or placement of eighth notes is to notice how your eighth notes fit with the rhythm section which is often playing off of the triplet... your eighth notes should be able to coexist with the triplet feel... Sometimes this means laying back on the eighth notes or putting some type of lob on the notes.' Chapter 18, p. 77.",
      "source_principle_ids": [
        "jerry-bergonzi:melodic-rhythms-vol-4:time-zone-gear-system"
      ],
      "source_work_id": "melodic-rhythms-vol-4",
      "references": [
        {
          "source": "melodic-rhythms-vol-4",
          "citation": "chapter 18 p. 77"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "f",
      "granularity_name": "rhythmic-placement"
    },
    {
      "chord_quality": "dom7",
      "function_role": "eighth-note-must-not-become-literal-triplets",
      "narrative": "Bergonzi explicitly warns against playing eighth notes as literal triplets over a dominant groove: 'This doesn't mean that your eighth notes should be played as triplets like in this example, but rather that your eighth notes should be able to coexist with the triplet feel.' The feel is internalised, not mechanically applied. Chapter 18, p. 77.",
      "source_principle_ids": [
        "jerry-bergonzi:melodic-rhythms-vol-4:time-zone-gear-system"
      ],
      "source_work_id": "melodic-rhythms-vol-4",
