      "granularity_name": "rhythmic-placement"
    },
    {
      "chord_quality": "dom7",
      "function_role": "chord-anticipation-grammar",
      "narrative": "Bergonzi prescribes practicing anticipating chord arrivals (including dominant arrivals) at offsets of 1/2 beat, 1 beat, 1\u00bd beats, 2 beats, 2\u00bd beats, and 3 beats as explicit rhythmic grammar rules. 'Anticipate chords by 1/2 beat, by 1 beat, by 1 1/2 beats, by 2 beats, by 2 1/2 beats, by 3 beats.' Chapter 29, p. 116.",
      "source_principle_ids": [
        "jerry-bergonzi:melodic-rhythms-vol-4:rhythmic-grammar"
      ],
      "source_work_id": "melodic-rhythms-vol-4",
