      "granularity_name": "rhythmic-placement"
    },
    {
      "chord_quality": "dom7",
      "function_role": "late-resolution-grammar",
      "narrative": "Over any chord change (including dominant resolutions), Bergonzi prescribes deliberately delaying resolution by 1 to 4 beats as a rhythmic grammar tool. 'Resolve late by 1 beat, 2 beats, 3 beats, or 4 beats.' Chapter 29, p. 116.",
      "source_principle_ids": [
        "jerry-bergonzi:melodic-rhythms-vol-4:rhythmic-grammar"
      ],
      "source_work_id": "melodic-rhythms-vol-4",
