    },
    {
      "chord_quality": "dom7",
      "function_role": "beat-one-phrase-boundary-proscription",
      "narrative": "Bergonzi's rhythmic grammar contains an absolute prohibition on starting or ending a phrase on beat one, applicable over all chord qualities. 'Never start on beat one. Never end on beat one.' Chapter 29, p. 116.",
      "source_principle_ids": [
        "jerry-bergonzi:melodic-rhythms-vol-4:rhythmic-grammar"
      ],
      "source_work_id": "melodic-rhythms-vol-4",
      "references": [
        {
