      "provenance": "extracted",
      "polarity": "proscriptive",
      "granularity_level": "f",
      "granularity_name": "rhythmic-placement"
    },
    {
      "chord_quality": "dom7",
      "function_role": "density-variation-constraint",
      "narrative": "Bergonzi prescribes that improvisers must alternate between passages that are predominantly eighth notes and passages that contain no eighth notes at all \u2014 avoiding the trap of relentless eighth-note density. 'Play predominantly eighth notes. Play without using eighth notes.' Chapter 29, p. 116; also Chapter 27, p. 110: 'Very often, less is more.'",
      "source_principle_ids": [
        "jerry-bergonzi:melodic-rhythms-vol-4:rhythmic-grammar"
      ],
      "source_work_id": "melodic-rhythms-vol-4",
      "references": [
