        }
      ],
      "provenance": "extracted",
      "granularity_level": "f",
      "granularity_name": "rhythmic-placement"
    },
    {
      "chord_quality": "dom7",
      "function_role": "eighth-note-trap-avoidance",
      "narrative": "At fast tempos over any chord, Bergonzi prescribes collapsing the felt pulse to 'two' or 'one' beat per measure to escape the eighth-note trap \u2014 the tendency to fill every subdivision. 'But if you want to get out of that zone for contrast try feeling the music in two or one. Try even perceiving a fast tune as a ballad.' Chapter 27, p. 111.",
      "source_principle_ids": [
        "jerry-bergonzi:melodic-rhythms-vol-4:time-zone-gear-system"
      ],
      "source_work_id": "melodic-rhythms-vol-4",
      "references": [
        {
          "source": "melodic-rhythms-vol-4",
          "citation": "chapter 27 p. 111"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "f",
      "granularity_name": "rhythmic-placement"
    },
    {
      "chord_quality": "dom7",
      "function_role": "silence-as-active-compositional-choice",
      "narrative": "Bergonzi prescribes treating silence and phrase endings as active compositional events over any chord context: 'Leave periods at the ends of sentences and paragraphs. Know when to end your solo. Listen to the rests. The listener will invite your next idea.' Chapter 29, p. 116.",
      "source_principle_ids": [
        "jerry-bergonzi:melodic-rhythms-vol-4:rhythmic-grammar"
      ],
      "source_work_id": "melodic-rhythms-vol-4",
