      "granularity_name": "other"
    },
    {
      "chord_quality": "dom7",
      "function_role": "five-time-zones-gear-taxonomy",
      "narrative": "Bergonzi prescribes expanding vocabulary by adapting any line to five distinct time zones or gears: quarter-note triplet, eighth-note, triplet, sixteenth-note, and sextuplet. These are interchangeable subdivisions deployable over any harmonic context. 'In this chapter we will consider five different time zones or gears to play in... The aim of this chapter is to expand your vocabulary by adapting lines to these varying time zones or gears.' Chapter 19, p. 82.",
      "source_principle_ids": [
        "jerry-bergonzi:melodic-rhythms-vol-4:time-zone-gear-system"
      ],
      "source_work_id": "melodic-rhythms-vol-4",
      "references": [
        {
          "source": "melodic-rhythms-vol-4",
          "citation": "chapter 19 p. 82"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "f",
      "granularity_name": "rhythmic-placement"
    },
    {
      "chord_quality": "dom7",
      "function_role": "groove-internalisation-slow-metronome",
      "narrative": "Bergonzi prescribes setting the metronome between 50 and 60 on the half note and repeating a line until triplets feel natural with eighth-note articulation. 'Set your metronome between 50 and 60 for the half note and play the line in its original form... Continue repeating the line until you are in the groove of triplets and phrasing them as if they were eighth notes.' Chapter 19, p. 83.",
      "source_principle_ids": [
        "jerry-bergonzi:melodic-rhythms-vol-4:time-zone-gear-system"
      ],
      "source_work_id": "melodic-rhythms-vol-4",
